Tool response:
Tool: extend_assignment_deadline
Description: Extend the submission deadline for a specific assignment by 48 hours. This endpoint requires instructor privileges for the course containing the assignment. The operation updates the assignment's deadline and creates notifications for all enrolled students.
Parameters:
    {
      "type": "object",
      "properties": {
        "assignment_id": {
          "type": "integer",
          "title": "Assignment Id",
          "description": ""
        },
        "hours": {
          "type": "integer",
          "minimum": 1,
          "default": 48,
          "title": "Hours",
          "description": ""
        }
      },
      "required": [
        "assignment_id"
      ]
    }
